CREATE OR REPLACE FUNCTION public.bootstrap_first_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.email_confirmed_at is null then
    return new;
  end if;

  if new.email is null or lower(split_part(new.email, '@', 2)) <> 'vedantix.nl' then
    return new;
  end if;

  if exists (select 1 from public.staff_users where active = true) then
    return new;
  end if;

  insert into public.staff_users (user_id, role, active)
  values (new.id, 'ADMIN', true)
  on conflict (user_id) do update
    set role = 'ADMIN', active = true;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_staff_invite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  invite_id uuid;
  invite_role text;
begin
  if new.email_confirmed_at is null or new.email is null then
    return new;
  end if;

  select i.id, i.role into invite_id, invite_role
  from public.staff_invites i
  where i.active = true and lower(i.email) = lower(new.email)
  order by i.created_at desc
  limit 1;

  if invite_id is null then
    return new;
  end if;

  insert into public.staff_users (user_id, role, active)
  values (new.id, invite_role, true)
  on conflict (user_id) do update set role = excluded.role, active = true;

  update public.staff_invites
  set active = false, accepted_by = new.id, accepted_at = now()
  where id = invite_id;

  return new;
end;
$function$
